const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang='zh',step=0,isDemo=false,helpId=null,helpTrigger=null;
const T=(zh,en,de)=>({zh,en,de})[lang];
const blank=()=>({year:'2025',name:'',group:'unknown',standard:'unknown',special:'unknown',germany:'unknown',revenues:['','','',''],upe:'unknown',upeName:'',parents:[],single:'unknown',common:'unknown',designated:'unknown',holds:'unknown',partial:'unknown',upperIIR:'unknown',qualified:'unknown',adjusted:'unknown',shSpecial:'unknown',history:'unknown',shRevenue:'',profit:'',tax:'',sbie:'',first:'unknown',girWhere:'unknown',girFiled:'unknown',exchange:'unknown',girEntity:'',girCountry:'unknown',notificationDone:'unknown'});let d=blank();
const knownCountries=['DE','NL','FR','BE','LU','IE','IT','ES','PT','AT','PL','CZ','DK','SE','FI','EE','LV','LT','MT','CY','GR','HR','SI','SK','HU','RO','BG','US','GB','CH','CN','JP'];
const country=k=>k==='unknown'?T('尚未确认','Not confirmed','Noch ungeklärt'):k==='OTHER'?T('其他国家／地区（需复核）','Other jurisdiction (review required)','Anderes Steuerhoheitsgebiet (Prüfung erforderlich)'):new Intl.DisplayNames([lang==='zh'?'zh-CN':lang],{type:'region'}).of(k);
const unknown=()=>T('尚未确认','Not confirmed','Noch ungeklärt');
const source=(n)=>`<a class="law" href="https://www.gesetze-im-internet.de/minstg/__${n}.html" target="_blank" rel="noopener">MinStG § ${n} ↗</a>`;
const refs=arr=>arr.map(source).join(' ');
const topicData=()=>({
 jv:{title:T('JV · 合营企业','JV · Joint Venture','JV · Joint Venture'),text:T('JV 是 Joint Venture 的缩写。最低税规则中的 JV 有专门定义，并非所有商业合资安排都自动按 JV 处理。符合条件的 JV 及其子公司可能需要单独进行安全港测试。','JV means Joint Venture. The minimum tax rules use a specific definition; not every commercial joint arrangement is treated as a JV. Qualifying JVs and their subsidiaries may require separate safe harbour testing.','JV steht für Joint Venture. Für die Mindeststeuer gilt eine besondere Definition; nicht jede wirtschaftliche Gemeinschaftsvereinbarung ist automatisch ein Joint Venture im gesetzlichen Sinn. Qualifizierende Joint Ventures und ihre Tochtergesellschaften können getrennt zu testen sein.'),refs:[67,85,90]},
 globe:{title:T('GloBE · 全球反税基侵蚀规则','GloBE · Global Anti-Base Erosion','GloBE · Globale Mindestbesteuerungsregeln'),text:T('GloBE 是 Global Anti-Base Erosion 的缩写，是 Pillar Two 全球最低税规则体系的常用名称。GIR 是该体系的信息申报表。具体德国义务以适用版本的 MinStG 为依据，不能仅凭 OECD 指引自动认定。','GloBE stands for Global Anti-Base Erosion, the commonly used name for the Pillar Two global minimum tax rules. The GIR is the associated information return. German obligations depend on the applicable MinStG provisions, not on OECD guidance alone.','GloBE steht für Global Anti-Base Erosion und bezeichnet die Regeln zur globalen Mindestbesteuerung unter Pillar Two. Der GIR ist der zugehörige Informationsbericht. Deutsche Pflichten richten sich nach der anwendbaren Fassung des MinStG, nicht allein nach OECD-Leitlinien.'),refs:[1,2,75]},
 law:{title:T('MinStG／BZSt · 德国法律与主管机构','MinStG / BZSt · German law and authority','MinStG / BZSt · Gesetz und Behörde'),text:T('MinStG 是 Mindeststeuergesetz（德国最低税法）的缩写。BZSt 是 Bundeszentralamt für Steuern（德国联邦中央税务局）的缩写，接收 Gruppenträgermeldung 和最低税信息报告。最低税税务申报与税款征管须另核主管 Finanzamt。','MinStG abbreviates Mindeststeuergesetz, Germany’s Minimum Tax Act. BZSt means Bundeszentralamt für Steuern, the Federal Central Tax Office, which receives group head notifications and minimum tax information reports. Check the competent Finanzamt separately for the tax return and tax administration.','MinStG steht für Mindeststeuergesetz. BZSt bezeichnet das Bundeszentralamt für Steuern, das Gruppenträgermeldungen und Mindeststeuer-Berichte entgegennimmt. Für Steuererklärung und Besteuerungsverfahren ist das zuständige Finanzamt gesondert zu bestimmen.'),refs:[3,75,95]},

 cbcr:{title:T('CbCR · 国别报告','CbCR · Country-by-Country Reporting','CbCR · Länderbezogene Berichterstattung'),text:T('CbCR 是 Country-by-Country Reporting 的缩写。它按税收管辖区列示集团收入、利润、税款及经营活动等信息。用于过渡期安全港的数据须符合“合格国别报告”要求；普通管理报表不能自动替代。CbCR 与 GIR 是不同报告。','CbCR stands for Country-by-Country Reporting. It presents group revenue, profit, taxes and business activity by jurisdiction. The transitional safe harbour requires a qualified CbC report; ordinary management accounts are not automatically sufficient. CbCR and the GIR are different reports.','CbCR steht für Country-by-Country Reporting. Der Bericht enthält nach Steuerhoheitsgebieten gegliederte Angaben zu Umsätzen, Ergebnissen, Steuern und Tätigkeiten. Für den Übergangs-Safe-Harbour ist ein qualifizierter länderbezogener Bericht erforderlich; interne Auswertungen reichen nicht automatisch aus. CbCR und GIR sind unterschiedliche Berichte.'),refs:[84,87]},
 etr:{title:T('ETR · 有效税率','ETR · Effective Tax Rate','ETR · Effektiver Steuersatz'),text:T('ETR 是 Effective Tax Rate 的缩写。本工具使用 CbCR 安全港的简化有效税率：简化涵盖税额 ÷ 经规定调整的税前利润。它不等于名义税率，也不等于完整 GloBE 有效税率。税前利润为零或亏损时不以该比率判断通过；请查看其他测试。','ETR means Effective Tax Rate. This tool uses the simplified ETR for the CbCR safe harbour: simplified covered taxes divided by adjusted profit before tax. It is neither the statutory tax rate nor the full GloBE ETR. A zero or negative denominator does not produce a passing ETR test; consider the other tests.','ETR bedeutet Effective Tax Rate. Hier wird der vereinfachte effektive Steuersatz für den CbCR-Safe-Harbour ermittelt: vereinfacht erfasste Steuern geteilt durch den angepassten Gewinn vor Steuern. Er entspricht weder dem nominalen noch dem vollständig berechneten GloBE-Steuersatz. Bei einem Nenner von null oder darunter wird dieser Test nicht als bestanden gewertet.'),refs:[87,53]},
 upe:{title:T('UPE · 最终母公司','UPE · Ultimate Parent Entity','UPE · Oberste Muttergesellschaft'),text:T('UPE 是集团最上层的母公司，需结合控制关系及集团定义确定，不一定是直接股东，也不一定是欧洲最高层实体。请按从最终母公司到德国实体的顺序填写中间母公司；德国和境外申报主体可能不同。','The UPE is the entity at the top of the group, determined under the ownership and group definitions. It is not necessarily the direct shareholder or the highest EU entity. Enter intermediate parents in order from the UPE down to the German entity. German filing responsibilities may sit with a different entity.','Die UPE ist die oberste Muttergesellschaft nach den gesetzlichen Gruppen- und Kontrollkriterien. Sie ist nicht zwingend die unmittelbare Gesellschafterin oder die höchste EU-Gesellschaft. Zwischengeschaltete Muttergesellschaften sind von oben nach unten einzutragen. Die deutschen Meldepflichten können eine andere Einheit treffen.'),refs:[4,7,8]},
 iir:{title:T('IIR · 所得纳入规则','IIR · Income Inclusion Rule','IIR · Primärergänzungssteuerregelung'),text:T('IIR 是 Income Inclusion Rule。德国对应 Primärergänzungssteuerregelung：母公司可能就低税实体承担补足税。中间母公司的上层适用认可 IIR 时，§ 8(2) 可能排除其该项义务，但必须核查年度、控制关系及母公司类型。部分持股母公司另按 § 8(3) 判断。','The Income Inclusion Rule may charge a parent with top-up tax relating to low-taxed entities. For an intermediate parent, an upper-tier parent subject to a qualified IIR may trigger the exception in section 8(2). Confirm the fiscal year, control relationship and entity classification. Partially-owned parent entities require a separate section 8(3) assessment.','Die Income Inclusion Rule entspricht der Primärergänzungssteuerregelung. Bei zwischengeschalteten Muttergesellschaften kann § 8 Abs. 2 eine Ausnahme vorsehen, wenn eine übergeordnete Muttergesellschaft einer anerkannten Regelung unterliegt. Geschäftsjahr, Kontrollbeteiligung und Einordnung sind zu prüfen. Für in Teileigentum stehende Muttergesellschaften gilt § 8 Abs. 3.'),refs:[8,9,10]},
 sbie:{title:T('SBIE · 实质性所得排除额','SBIE · Substance-based Income Exclusion','SBIE · Substanzbasierter Freibetrag'),text:T('SBIE 根据符合条件的工资成本和有形资产账面价值及对应年度的比例计算。此处填写已核算的排除额，不是工资或资产原值。常规利润测试将经调整税前利润与 SBIE 比较。','The SBIE is calculated using eligible payroll costs and carrying values of tangible assets, with the percentages applicable to the fiscal year. Enter the calculated exclusion, not gross payroll or asset values. The routine profits test compares adjusted profit before tax with this exclusion.','Der substanzbasierte Freibetrag wird anhand berücksichtigungsfähiger Lohnkosten und Buchwerte materieller Vermögenswerte mit den für das Geschäftsjahr geltenden Prozentsätzen berechnet. Einzutragen ist der berechnete Freibetrag, nicht die Lohn- oder Vermögenssumme. Der Routinegewinn-Test vergleicht ihn mit dem angepassten Gewinn vor Steuern.'),refs:[58,59,60,61,62,84]},
 gir:{title:T('GIR · GloBE 信息申报表','GIR · GloBE Information Return','GIR · Mindeststeuer-Bericht'),text:T('GIR 是 GloBE Information Return。德国称 Mindeststeuer-Bericht，用于报告集团结构、税额计算及选择权等信息；它不是德国最低税税务申报表。境外提交只有在提交主体及相关年度交换条件满足时，才可能免除德国本地提交。','GIR means GloBE Information Return, called Mindeststeuer-Bericht in Germany. It reports group structure, calculations and elections. It is separate from the German minimum tax return. Foreign filing may relieve local GIR filing only if the filing entity and exchange conditions for the fiscal year are satisfied.','GIR steht für GloBE Information Return, in Deutschland Mindeststeuer-Bericht. Er enthält Angaben zur Gruppenstruktur, zu Berechnungen und Wahlrechten und ist von der Mindeststeuererklärung zu unterscheiden. Eine Auslandsabgabe kann die lokale Berichtspflicht nur bei Erfüllung der Voraussetzungen für Übermittler und Informationsaustausch ersetzen.'),refs:[75,76,95]},
 head:{title:T('Gruppenträger · 德国最低税集团主申报主体','Gruppenträger · German minimum tax group head','Gruppenträger der Mindeststeuergruppe'),text:T('Gruppenträger 是德国最低税集团的法定责任主体，并不等同于企业所得税 Organschaft 的 Organträger。一般依次核查德国 UPE、共同德国母公司及 UPE 指定实体；只有一个德国应税实体时也可构成最低税集团。未知信息不能当作“否”。','The Gruppenträger is the responsible entity of the German minimum tax group, not the Organträger of a corporate income tax group. Assess the German UPE, common German parent and UPE designation in the statutory order. A single German taxable entity can also constitute a minimum tax group. Unknown answers must not be treated as “No”.','Der Gruppenträger ist die verantwortliche Einheit der deutschen Mindeststeuergruppe und nicht mit dem Organträger einer körperschaftsteuerlichen Organschaft gleichzusetzen. Zu prüfen sind insbesondere die deutsche UPE, die gemeinsame inländische Muttergesellschaft und eine Bestimmung durch die UPE. Auch eine einzelne inländische steuerpflichtige Einheit bildet eine Mindeststeuergruppe. Ungeklärte Angaben sind kein „Nein“.'),refs:[3]},
 scope:{title:T('集团范围与收入门槛','Group scope and revenue threshold','Gruppenumfang und Umsatzgrenze'),text:T('一般要求前四个财年至少两个财年的 UPE 合并收入达到 7.5 亿欧元。不是看德国单体收入。排除实体的收入仍可能计入门槛；非十二个月财年、集团合并或分拆、JV 等需特别处理。此原型限于已确认的十二个月日历财年及欧元口径。','The general threshold is EUR 750 million of UPE consolidated revenue in at least two of the four preceding fiscal years, not the revenue of the German entity alone. Excluded-entity revenue can still count. Short or long years, mergers, demergers and JVs require special treatment. This prototype assumes confirmed calendar years and EUR amounts.','Die allgemeine Umsatzgrenze beträgt 750 Mio. EUR im Konzernabschluss der UPE in mindestens zwei der vier vorhergehenden Geschäftsjahre. Der Einzelumsatz der deutschen Gesellschaft ist nicht maßgeblich. Umsätze ausgeschlossener Einheiten können mitzählen. Rumpfjahre, Umstrukturierungen und Joint Ventures erfordern Sonderprüfungen. Der Prototyp setzt bestätigte Kalendergeschäftsjahre und EUR-Werte voraus.'),refs:[1,4,5,63,90]},
 year:{title:T('财年与期限','Fiscal years and deadlines','Geschäftsjahre und Fristen'),text:T('本版支持 2024–2026 日历财年的初筛。GIR 一般在财年结束后 15 个月提交，集团首次编报为 18 个月，并有不早于 2026 年 6 月 30 日的规定。德国税务申报期限不早于相应 GIR 期限，但不能直接把两者等同。名义日期仍需核查周末、节假日和个案延期。','This version screens calendar fiscal years 2024–2026. GIR filing is generally due 15 months after year-end, or 18 months for the group’s first reporting year, and not before 30 June 2026. The German tax return deadline cannot precede the relevant GIR deadline; they are not necessarily identical. Check weekends, holidays and individual extensions.','Diese Version prüft Kalendergeschäftsjahre 2024–2026. Der Mindeststeuer-Bericht ist grundsätzlich nach 15 Monaten, im erstmaligen Berichtsjahr nach 18 Monaten, jedoch nicht vor dem 30. Juni 2026 abzugeben. Die Frist der Steuererklärung endet nicht vor der maßgeblichen Berichtsfrist, muss ihr aber nicht entsprechen. Wochenenden, Feiertage und Fristverlängerungen sind gesondert zu prüfen.'),refs:[75,94,95,101]},
 safe:{title:T('过渡期 CbCR 安全港','Transitional CbCR Safe Harbour','Übergangsregelung: CbCR-Safe-Harbour'),text:T('按税收管辖区测试，原则上三个数值测试之一满足即可，但还须核查合格数据、必要调整、申请及连续适用条件。通过不等于所有申报义务消失，也不意味着本工具已算出补足税为零。其他安全港及 2026 年 OECD 新措施的德国适用情况不在本模块的自动判断范围。','This is a jurisdiction-level test. One numerical test can suffice, subject to qualified data, required adjustments, election and continuity conditions. Passing does not eliminate all filing obligations or mean this tool calculated zero tax. Other safe harbours and German implementation of new 2026 OECD measures are outside automated assessment.','Geprüft wird auf Ebene des Steuerhoheitsgebiets. Ein erfüllter Zahlentest kann genügen, sofern Datenqualität, Anpassungen, Antrag und Kontinuitätsbedingungen vorliegen. Ein positives Ergebnis beseitigt nicht alle Erklärungspflichten und ist keine Steuerberechnung. Andere Safe Harbours und die deutsche Anwendung neuer OECD-Maßnahmen von 2026 werden nicht automatisch geprüft.'),refs:[78,84,87]},
 adjustments:{title:T('合格数据与必要调整','Qualified data and required adjustments','Qualifizierte Daten und erforderliche Anpassungen'),text:T('确认数据源符合 § 87、使用口径一致，并完成所有适用调整，包括收购会计和错配安排。不确定时请选择“尚未确认”；工具会保留数值演算，但不出具资格通过结论。','Confirm section 87 data quality and consistency and all applicable adjustments, including purchase price accounting and hybrid arrangements. Select “Not confirmed” if uncertain. Numerical calculations remain visible, but eligibility will not be treated as established.','Zu bestätigen sind Datenqualität und Konsistenz nach § 87 sowie sämtliche erforderlichen Anpassungen, einschließlich Erwerbsmethode und Inkongruenzen. Bei Unsicherheit ist „Noch ungeklärt“ zu wählen. Die Zahlenprüfung bleibt sichtbar; die Anspruchsberechtigung gilt jedoch nicht als bestätigt.'),refs:[87,'87a','87b']},
 history:{title:T('连续适用与“退出后受限”','Continuity and the “once out, always out” rule','Kontinuität und Ausschluss in Folgejahren'),text:T('此前未申请或未满足条件，通常会限制该管辖区后续年度适用；上年度该辖区没有集团实体等法定例外需单独核实。“本年首次适用”本身并不自动消除此前的限制。','Failure to elect or qualify in an earlier year generally restricts later use in that jurisdiction. Verify statutory exceptions, including no constituent entity in that jurisdiction in the preceding year. Calling the current year the first application year does not itself remove a previous restriction.','Ein unterbliebener Antrag oder fehlende Voraussetzungen können die Anwendung in Folgejahren ausschließen. Gesetzliche Ausnahmen, insbesondere das Fehlen einer Geschäftseinheit im betreffenden Steuerhoheitsgebiet im Vorjahr, sind gesondert zu prüfen. Die Bezeichnung als erstmaliges Anwendungsjahr beseitigt einen früheren Ausschluss nicht.'),refs:[84]},
 taxes:{title:T('简化涵盖税额','Simplified covered taxes','Vereinfacht erfasste Steuern'),text:T('这里是经 § 87(4) 调整后的所得税费用口径，不是现金实缴税款。需剔除不涵盖税种、不确定税收事项及其他规定调整。填写已核验金额。','Use income tax expense adjusted under section 87(4), not cash taxes paid. Remove non-covered taxes, uncertain tax positions and other prescribed adjustments. Enter a verified amount.','Maßgeblich ist der nach § 87 Abs. 4 bereinigte Ertragsteueraufwand, nicht die gezahlte Steuer. Nicht erfasste Steuern, ungewisse Steuerpositionen und weitere vorgeschriebene Korrekturen sind zu berücksichtigen. Bitte einen geprüften Wert eintragen.'),refs:[87]},
 profit:{title:T('测试数据 · 德国辖区','Test inputs · German jurisdiction','Testdaten · Steuerhoheitsgebiet Deutschland'),text:T('收入及税前利润按合格 CbCR 及法定调整口径填写，单位为百万欧元。德国所有相关实体须按规则汇总；JV 等可能单独测试。不同测试可能需要不同实体范围或调整，如有此情况应标记特殊情形并专项复核。','Enter qualified CbCR revenue and profit before tax after prescribed adjustments, in EUR millions. Aggregate relevant German entities under the rules; JVs may require separate testing. If test-specific perimeters or adjustments differ, flag a special case and obtain a separate review.','Umsatz und Ergebnis vor Steuern sind nach qualifiziertem CbCR und gesetzlichen Anpassungen in Mio. EUR anzugeben. Relevante deutsche Einheiten sind regelkonform zusammenzufassen; Joint Ventures können getrennt zu testen sein. Abweichende Testabgrenzungen oder Anpassungen sind als Sonderfall zu kennzeichnen.'),refs:[84,85,86,87]},
 eu:{title:T('欧盟上层母公司与所在地','EU parent entities and location','Übergeordnete EU-Muttergesellschaften und Belegenheit'),text:T('欧盟不等于欧洲：英国、瑞士不是欧盟成员国。单凭上层母公司所在地不能确定境外税负或免除德国义务。需核查完整控制链及相关财年的当地规则；“其他国家”须进一步确认。','The EU is not the same as Europe: the UK and Switzerland are not EU members. An upper parent’s location alone does not establish foreign tax liability or remove German obligations. Review the full control chain and fiscal-year-specific local rules. “Other jurisdiction” requires further identification.','EU und Europa sind nicht gleichzusetzen: Das Vereinigte Königreich und die Schweiz sind keine EU-Mitglieder. Die Belegenheit einer übergeordneten Muttergesellschaft allein begründet weder eine ausländische Steuerpflicht noch eine deutsche Befreiung. Kontrollkette und jahresbezogene lokale Regeln sind zu prüfen.'),refs:[6,8]},
 return:{title:T('德国最低税申报与支付','German minimum tax return and payment','Mindeststeuererklärung und Zahlung'),text:T('德国 Gruppenträger 按 § 95 以 Steueranmeldung 形式自行计算并申报最低税。GIR 是独立的信息报告。一般税款在提交税务申报后一个月到期。原型不计算税额，也不进行电子报送。','The German Gruppenträger self-assesses minimum tax in a Steueranmeldung under section 95. The GIR is a separate information return. Payment is generally due one month after filing the tax return. This prototype neither computes the tax nor transmits a filing.','Der Gruppenträger berechnet die Mindeststeuer in einer Steueranmeldung nach § 95 selbst. Der Mindeststeuer-Bericht ist davon getrennt. Die Steuer ist grundsätzlich einen Monat nach Abgabe der Steuererklärung fällig. Der Prototyp berechnet keine Steuer und übermittelt keine Erklärung.'),refs:[95]},
 utpr:{title:T('UTPR · 低税利润规则','UTPR · Undertaxed Profits Rule','UTPR · Sekundärergänzungssteuerregelung'),text:T('UTPR 是对未被 IIR 充分征税的低税利润发挥补充作用的规则。它与德国国内补足税和 IIR 是不同路径。本原型仅列明该概念，不计算 UTPR 分配或税额。','The UTPR provides a backstop for low-taxed profits not fully brought into charge under an IIR. It is distinct from domestic top-up tax and the IIR. This prototype explains the term but does not calculate UTPR allocation or tax.','Die UTPR ergänzt die IIR für niedrig besteuerte Gewinne, die nicht vollständig durch eine IIR erfasst werden. Sie ist von der nationalen Ergänzungssteuer zu unterscheiden. Der Prototyp erläutert den Begriff, berechnet aber weder Verteilung noch Steuerbetrag.'),refs:[11,12,101]},
 qdmtt:{title:T('QDMTT · 合格国内最低补足税','QDMTT · Qualified Domestic Minimum Top-up Tax','QDMTT · Anerkannte nationale Ergänzungssteuer'),text:T('QDMTT 是辖区对本地低税利润征收、并获得认可地位的国内最低补足税。德国称 nationale Ergänzungssteuer；认可状态及适用年度须核验。境外母公司适用 IIR，并不自动排除德国国内补足税。','A QDMTT is a domestic minimum top-up tax on local low-taxed profits that has qualified status. Germany uses the term nationale Ergänzungssteuer. Verify recognition and the relevant fiscal year. A foreign parent applying an IIR does not automatically displace German domestic top-up tax.','Eine QDMTT ist eine anerkannte nationale Ergänzungssteuer auf inländische niedrig besteuerte Gewinne. Anerkennungsstatus und Anwendungsjahr sind zu prüfen. Eine IIR bei der ausländischen Muttergesellschaft schließt die deutsche nationale Ergänzungssteuer nicht automatisch aus.'),refs:[90,91,92,93]},
 notification:{title:T('Gruppenträgermeldung · 集团主体通知','Gruppenträgermeldung · Group head notification','Gruppenträgermeldung'),text:T('向 BZSt 通知德国最低税集团的 Gruppenträger 身份。首次通知与主体变更须分别核查，不能一概视为每年重新登记。一般期限为课税期间结束后两个月，课税期间为日历年。此处“已完成”也要求核查后续变更。','This notifies the BZSt of the German minimum tax group head. Check initial notification and changes separately; do not assume a fresh registration is required every year. The general deadline is two months after the calendar-year tax period. “Completed” also requires checking later changes.','Die Meldung informiert das BZSt über die Stellung als Gruppenträger. Erstmeldung und Änderungen sind getrennt zu prüfen; eine jährliche Neuregistrierung darf nicht pauschal unterstellt werden. Die allgemeine Frist beträgt zwei Monate nach Ablauf des kalenderjährlichen Besteuerungszeitraums. Auch spätere Änderungen sind zu berücksichtigen.'),refs:[3,94]}
});
const fields=()=>({
 name:[T('德国企业名称','German entity name','Name der deutschen Einheit'),'scope'],year:[T('待评估日历财年','Calendar fiscal year under review','Zu prüfendes Kalendergeschäftsjahr'),'year'],group:[T('是否属于企业集团？','Is the entity part of a group?','Gehört die Einheit zu einer Unternehmensgruppe?'),'scope'],germany:[T('集团是否在德国存在实体或常设机构？','Does the group have an entity or permanent establishment in Germany?','Hat die Gruppe eine Einheit oder Betriebsstätte in Deutschland?'),'scope'],standard:[T('本年与前四年是否均为十二个月日历财年，且收入已按适用规则换算为欧元？','Are this year and the preceding four years all 12-month calendar years, with revenue converted to EUR under the applicable rules?','Sind dieses und die vier vorhergehenden Geschäftsjahre zwölfmonatige Kalenderjahre und die Umsätze regelkonform in EUR umgerechnet?'),'year'],special:[T('是否涉及排除实体、JV、重组、新设集团等特殊范围问题？','Are there excluded entities, JVs, reorganisations, newly formed groups or other scope complications?','Liegen ausgeschlossene Einheiten, Joint Ventures, Umstrukturierungen, neu gegründete Gruppen oder andere Sonderfälle vor?'),'scope'],upeName:[T('最终母公司名称','Ultimate parent entity name','Name der obersten Muttergesellschaft'),'upe'],upe:[T('最终母公司所在国家／地区','UPE jurisdiction','Steuerhoheitsgebiet der UPE'),'upe'],holds:[T('德国实体是否持有其他集团实体权益？','Does the German entity hold ownership interests in other group entities?','Hält die deutsche Einheit Beteiligungen an anderen Gruppeneinheiten?'),'iir'],partial:[T('是否涉及外部少数股东或部分持股母公司？','Are there outside minority interests or partially-owned parent entities?','Gibt es externe Minderheitsbeteiligungen oder in Teileigentum stehende Muttergesellschaften?'),'iir'],upperIIR:[T('是否已确认该年度 UPE 或具有控制关系的上层母公司适用认可 IIR？','Is it confirmed that the UPE or a controlling upper-tier parent is subject to a qualified IIR for this fiscal year?','Ist bestätigt, dass die UPE oder eine übergeordnete kontrollierende Muttergesellschaft im betreffenden Geschäftsjahr einer anerkannten IIR unterliegt?'),'iir'],single:[T('是否仅有一家德国应税实体？','Is there only one taxable German constituent entity?','Gibt es nur eine steuerpflichtige deutsche Geschäftseinheit?'),'head'],common:[T('是否存在所有德国应税实体的共同德国母公司？','Is there a common German parent of all taxable German entities?','Gibt es eine gemeinsame inländische Muttergesellschaft aller steuerpflichtigen deutschen Einheiten?'),'head'],designated:[T('若无上述主体，UPE 是否已指定德国 Gruppenträger？','If the preceding routes do not apply, has the UPE designated a German group head?','Falls die vorrangigen Fälle nicht vorliegen: Hat die UPE einen deutschen Gruppenträger bestimmt?'),'head'],qualified:[T('是否已确认合格 CbCR 及会计数据的一致性？','Are the CbC report and underlying accounting data confirmed as qualified and consistent?','Sind der länderbezogene Bericht und die zugrunde liegenden Rechnungslegungsdaten nachweislich qualifiziert und konsistent?'),'cbcr'],adjusted:[T('是否已完成全部适用的数据调整？','Have all applicable data adjustments been made?','Wurden sämtliche erforderlichen Datenanpassungen vorgenommen?'),'adjustments'],shSpecial:[T('是否涉及 JV、投资实体、透明实体或不同测试口径等特殊情况？','Are there JVs, investment or flow-through entities, different test perimeters or other special cases?','Liegen Joint Ventures, Investment- oder transparente Einheiten, abweichende Testabgrenzungen oder andere Sonderfälle vor?'),'profit'],history:[T('该辖区此前的安全港适用情况','Prior safe harbour status for this jurisdiction','Bisherige Safe-Harbour-Anwendung im Steuerhoheitsgebiet'),'history'],shRevenue:[T('已调整 CbCR 收入及其他收益 · €m','Adjusted CbCR revenue and other income · EUR m','Angepasste CbCR-Umsatzerlöse und sonstige Erträge · Mio. EUR'),'profit'],profit:[T('已调整税前利润／亏损 · €m','Adjusted profit / loss before tax · EUR m','Angepasster Gewinn / Verlust vor Steuern · Mio. EUR'),'profit'],tax:[T('简化涵盖税额 · €m','Simplified covered taxes · EUR m','Vereinfacht erfasste Steuern · Mio. EUR'),'taxes'],sbie:[T('已核算 SBIE · €m','Calculated SBIE · EUR m','Berechneter substanzbasierter Freibetrag · Mio. EUR'),'sbie'],first:[T('该年是否为集团首次需要编制 GIR 的财年？','Is this the first fiscal year for which the group must prepare a GIR?','Ist dies das erste Geschäftsjahr, für das die Gruppe einen Mindeststeuer-Bericht erstellen muss?'),'year'],girWhere:[T('GIR 提交安排','GIR filing arrangement','Übermittlung des Mindeststeuer-Berichts'),'gir'],girEntity:[T('GIR 提交实体名称','GIR filing entity name','Name der berichtsübermittelnden Einheit'),'gir'],girCountry:[T('境外 GIR 提交所在地','Foreign GIR filing jurisdiction','Ausländisches Steuerhoheitsgebiet der GIR-Abgabe'),'gir'],girFiled:[T('境外 GIR 是否已由 UPE 或其指定实体按要求提交？','Has the foreign GIR been duly filed by the UPE or its designated entity?','Wurde der GIR im Ausland ordnungsgemäß durch die UPE oder eine beauftragte Einheit übermittelt?'),'gir'],exchange:[T('是否已核验对应年度的欧盟／有效自动交换条件？','Have the EU / effective automatic exchange conditions for this fiscal year been verified?','Sind die EU- bzw. wirksamen automatischen Austauschbedingungen für dieses Geschäftsjahr geprüft?'),'gir'],notificationDone:[T('是否已完成适用的 Gruppenträgermeldung，并核查后续变更？','Has the applicable group head notification been completed, including a review of subsequent changes?','Ist die erforderliche Gruppenträgermeldung erfolgt und wurden nachfolgende Änderungen geprüft?'),'notification']
});
const optionSets=()=>({yn:{unknown:unknown(),yes:T('是','Yes','Ja'),no:T('否','No','Nein')},history:{unknown:unknown(),eligible:T('持续符合／首次适用且无历史限制','Previously eligible / no prior restriction','Bisher berechtigt / kein früherer Ausschluss'),blocked:T('此前未申请／不符合，且没有可用例外','Previously not elected / not eligible, with no applicable exception','Früher kein Antrag / keine Berechtigung; keine anwendbare Ausnahme')},girWhere:{unknown:unknown(),DE:T('德国本地提交','File in Germany','Übermittlung in Deutschland'),foreign:T('境外提交','File abroad','Übermittlung im Ausland')},year:{2024:'2024',2025:'2025',2026:'2026'},countries:Object.fromEntries(['unknown',...knownCountries,'OTHER'].map(k=>[k,country(k)]))});
function help(topic){return `<button type="button" class="help" data-help="${topic}" aria-label="${esc(T('解释：','Explain: ','Erläuterung: ')+topicData()[topic].title)}" aria-haspopup="dialog">?</button>`}
function field(k,type='select',options){const [label,topic]=fields()[k];const id='field-'+k;const opts=options||optionSets()[k]||(['upe','girCountry'].includes(k)?optionSets().countries:optionSets().yn);return `<div class="field"><div class="field-label"><label for="${id}">${label}</label>${help(topic)}</div>${type==='select'?`<select id="${id}" data-key="${k}">${Object.entries(opts).map(([v,t])=>`<option value="${v}" ${d[k]===v?'selected':''}>${esc(t)}</option>`).join('')}</select>`:`<input id="${id}" data-key="${k}" type="${type}" value="${esc(d[k])}" ${type==='number'?`step="any" ${['shRevenue','sbie'].includes(k)?'min="0"':''}`:''}>`}</div>`}
const panel=(title,body,topic)=>`<div class="panel"><h3>${title} ${topic?help(topic):''}</h3>${body}</div>`;
const heading=(n,title,text)=>`<div class="section-kicker">0${n} / PILLAR TWO</div><h1>${title}</h1><p class="intro">${text}</p>`;
function chain(){return [{name:d.upeName||T('最终母公司','Ultimate parent','Oberste Muttergesellschaft'),country:d.upe},...d.parents.map(p=>({name:p.name||T('中间母公司','Intermediate parent','Zwischengeschaltete Muttergesellschaft'),country:p.country})),{name:d.name||T('德国受评估实体','German entity under review','Geprüfte deutsche Einheit'),country:'DE'}].map((p,i)=>`${i?'<div class="chain-arrow">↓</div>':''}<div class="chain-node">${esc(p.name)}<small>${esc(country(p.country))}${P2.EU.includes(p.country)?' · EU':''}</small></div>`).join('')}
function scopePage(){return heading(1,T('先确认，是否进入适用范围。','Start with the scope of the rules.','Zuerst den Anwendungsbereich klären.'),T('以集团合并收入为起点，金额单位为百万欧元。每个问号均可打开解释及法条。','Start with consolidated group revenue, in EUR millions. Each question mark opens an explanation and legal references.','Ausgangspunkt ist der Konzernumsatz in Mio. EUR. Jedes Fragezeichen öffnet eine Erläuterung mit Rechtsgrundlagen.'))+panel(T('评估对象','Entity and assumptions','Einheit und Annahmen'),`<div class="grid">${field('name','text')}${field('year')}</div>${['group','germany','standard','special'].map(k=>field(k)).join('')}`)+panel(T('前四个财年 · 集团合并收入','Consolidated revenue · preceding four years','Konzernumsatz · vier vorhergehende Geschäftsjahre'),`<p class="hint">${T('留空表示未知，0 表示已确认零收入。','Leave blank for unknown; 0 means confirmed zero revenue.','Leer bedeutet ungeklärt; 0 bedeutet bestätigten Nullumsatz.')}</p>${d.revenues.map((v,i)=>`<div class="revenue-row"><label for="revenue-${i}">${Number(d.year)-4+i}</label><input id="revenue-${i}" aria-label="${Number(d.year)-4+i} ${T('集团收入','group revenue','Konzernumsatz')}" type="number" min="0" step="any" data-revenue="${i}" value="${esc(v)}"><span>€m ${help('scope')}</span></div>`).join('')}<p class="hint">${T('至少 2 / 4 年达到 €750m。非标准财年和特殊情形需专项复核。','At least 2 of 4 years must reach EUR 750m. Non-standard years and special cases require review.','Mindestens 2 von 4 Jahren müssen 750 Mio. EUR erreichen. Abweichende Geschäftsjahre und Sonderfälle sind gesondert zu prüfen.')}</p>`,'scope')}
function structurePage(){return heading(2,T('沿着持股链，定位责任。','Follow the ownership chain.','Verantwortung entlang der Beteiligungskette.'),T('上层存在欧盟母公司，并不代表德国本地义务消失。','An EU parent higher in the chain does not remove all German obligations.','Eine übergeordnete EU-Muttergesellschaft beseitigt nicht sämtliche deutschen Pflichten.'))+panel(T('最终母公司','Ultimate parent entity','Oberste Muttergesellschaft'),`<div class="grid">${field('upeName','text')}${field('upe')}</div>`,'upe')+panel(T('中间母公司 · 从高到低','Intermediate parents · top to bottom','Zwischengeschaltete Muttergesellschaften · von oben nach unten'),`${d.parents.map((p,i)=>`<div class="parent"><div class="field"><div class="field-label"><label for="pn-${i}">${T('名称','Name','Name')}</label>${help('upe')}</div><input id="pn-${i}" data-parent-name="${i}" value="${esc(p.name)}"></div><div class="field"><div class="field-label"><label for="pc-${i}">${T('所在地','Jurisdiction','Steuerhoheitsgebiet')}</label>${help('eu')}</div><select id="pc-${i}" data-parent-country="${i}">${Object.entries(optionSets().countries).map(([v,t])=>`<option value="${v}" ${v===p.country?'selected':''}>${esc(t)}</option>`).join('')}</select></div><button class="textbtn" data-remove="${i}">${T('删除','Remove','Entfernen')}</button></div>`).join('')}<button class="secondary" id="addParent">＋ ${T('添加一层母公司','Add a parent entity','Muttergesellschaft hinzufügen')}</button><p class="hint">${T('只填写上层控制链，不填姐妹公司。交叉持股及复杂结构需另行复核。','Enter controlling parents, not sister entities. Cross-holdings and complex structures need separate review.','Nur übergeordnete kontrollierende Gesellschaften eintragen, keine Schwestergesellschaften. Kreuzbeteiligungen und komplexe Strukturen gesondert prüfen.')}</p>`,'eu')+panel(T('德国实体的角色','Role of the German entity','Rolle der deutschen Einheit'),['holds','partial','upperIIR','single','common','designated'].map(k=>field(k)).join(''),'head')+panel(T('持股链预览','Ownership chain preview','Vorschau der Beteiligungskette'),`<div id="chain">${chain()}</div>`,'upe')}
function safePage(){return heading(3,T('先做数值测试，再核实资格。','Test the numbers. Verify eligibility.','Zahlen testen. Voraussetzungen prüfen.'),T('测试德国整个税收管辖区的过渡期 CbCR 安全港。','Screen the Transitional CbCR Safe Harbour for the German jurisdiction.','Prüfung des CbCR-Safe-Harbours für das Steuerhoheitsgebiet Deutschland.'))+panel(T('数据资格与连续适用','Data quality and continuity','Datenqualität und Kontinuität'),['qualified','adjusted','shSpecial','history'].map(k=>field(k)).join(''),'safe')+panel(T('已调整数据 · 百万欧元','Adjusted inputs · EUR millions','Angepasste Werte · Mio. EUR'),`<div class="grid">${['shRevenue','profit','tax','sbie'].map(k=>field(k,'number')).join('')}</div><div id="tests"></div>`,'profit')+`<div class="notice">${T('通过数值测试不等于自动免报。SBIE 须先按适用年度核算；其他安全港尚未评估。','Passing a numerical test does not automatically remove filing duties. Calculate the year-specific SBIE first. Other safe harbours are not assessed.','Ein bestandener Zahlentest befreit nicht automatisch von Meldepflichten. Der SBIE ist vorab jahresbezogen zu berechnen. Andere Safe Harbours werden nicht geprüft.')}</div>`}
function filingPage(){return heading(4,T('把“谁来报”与“报什么”分开。','Separate the filer from the filing.','Wer meldet was?'),T('GIR、德国税务申报和集团主体通知是独立事项。','The GIR, German tax return and group head notification are separate obligations.','Mindeststeuer-Bericht, Steuererklärung und Gruppenträgermeldung sind getrennte Pflichten.'))+panel('GIR / Mindeststeuer-Bericht',field('first')+field('girWhere')+`<div class="grid">${field('girEntity','text')}${field('girCountry')}</div>`+field('girFiled')+field('exchange'),'gir')+panel(T('德国集团主体通知','German group head notification','Deutsche Gruppenträgermeldung'),field('notificationDone'),'notification')}
function status(k){return ({yes:T('初步进入范围','Provisionally in scope','Vorläufig im Anwendungsbereich'),no:T('初步不在范围','Provisionally out of scope','Vorläufig nicht im Anwendungsbereich'),unknown:T('资料不足','Insufficient information','Angaben unvollständig'),review:T('需要复核','Review required','Prüfung erforderlich'),pass:T('初筛通过 · 须留证','Screen passed · evidence required','Vorprüfung bestanden · Nachweise erforderlich'),fail:T('数值测试未通过','Numerical tests not passed','Zahlentests nicht bestanden'),blocked:T('连续适用受限','Continuity restriction','Ausschluss in Folgejahren'),invalid:T('数据资格不满足','Data not qualified','Daten nicht qualifiziert')})[k]}
function roleText(k){return ({upe:T('德国 UPE 是 Gruppenträger。','The German UPE is the group head.','Die deutsche UPE ist Gruppenträger.'),single:T('唯一德国应税实体是 Gruppenträger。','The sole taxable German entity is the group head.','Die einzige steuerpflichtige deutsche Einheit ist Gruppenträger.'),common:T('共同德国母公司是 Gruppenträger。','The common German parent is the group head.','Die gemeinsame deutsche Muttergesellschaft ist Gruppenträger.'),designated:T('由 UPE 指定的德国实体为 Gruppenträger。','The German entity designated by the UPE is the group head.','Die von der UPE bestimmte deutsche Einheit ist Gruppenträger.'),fallback:T('未指定主体：须按适用法律核查经济上最重要的德国实体。','No entity designated: review the economically most significant German entity under the applicable law.','Keine Bestimmung: Die wirtschaftlich bedeutendste deutsche Einheit ist nach der anwendbaren Rechtslage zu prüfen.'),unknown:T('资料尚不足以确定 Gruppenträger。','Insufficient information to determine the group head.','Der Gruppenträger lässt sich anhand der Angaben noch nicht bestimmen.')})[k]}
function iirText(k){return ({partial:T('外部持股或母公司分类尚需专项复核。','Outside ownership or parent classification needs separate review.','Externe Beteiligungen oder die Einordnung der Muttergesellschaft erfordern eine Sonderprüfung.'),upe:T('德国 UPE：进入 IIR 适用评估。','German UPE: assess IIR application.','Deutsche UPE: Anwendung der IIR prüfen.'),unknown:T('母公司所在地或德国实体持股角色尚未确认。','Parent location or German ownership role is not confirmed.','Belegenheit der Muttergesellschaft oder Beteiligungsrolle der deutschen Einheit ist ungeklärt.'),nohold:T('没有填写下层持股；仍须核查实体分类及其他最低税路径。','No downstream interests reported; entity classification and other minimum tax routes still need review.','Keine nachgelagerten Beteiligungen angegeben; Einordnung und weitere Mindeststeuerregeln bleiben zu prüfen.'),exception:T('上层认可 IIR 可能触发德国中间母公司的 § 8(2) 例外。','An upper-tier qualified IIR may trigger the section 8(2) exception for a German intermediate parent.','Eine übergeordnete anerkannte IIR kann die Ausnahme des § 8 Abs. 2 für eine deutsche zwischengeschaltete Muttergesellschaft auslösen.'),review:T('德国中间母公司的 IIR 适用情况需进一步评估。','Further assessment of the German intermediate parent’s IIR position is required.','Die IIR-Position der deutschen zwischengeschalteten Muttergesellschaft ist weiter zu prüfen.')})[k]}
function girText(k){return ({local:T('已选择德国本地提交 GIR。','GIR filing in Germany selected.','GIR-Übermittlung in Deutschland ausgewählt.'),foreign:T('境外提交路径初步满足本地免交条件；留存证据。','Foreign filing provisionally meets local filing relief conditions; retain evidence.','Die Auslandsabgabe erfüllt vorläufig die Voraussetzungen für die lokale Abgabebefreiung; Nachweise aufbewahren.'),review:T('德国本地提交义务尚未排除；核查境外提交与交换条件。','Local German filing has not been ruled out; verify foreign submission and exchange conditions.','Eine lokale Abgabepflicht ist nicht ausgeschlossen; Auslandsabgabe und Austauschbedingungen prüfen.')})[k]}
function testHTML(a){const names=[T('微利测试','De minimis test','CbCR-Wesentlichkeitsgrenze-Test'),T('简化有效税率测试','Simplified ETR test','CbCR-Effektivsteuersatz-Test'),T('常规利润测试','Routine profits test','CbCR-Routinegewinn-Test')],desc=[T('收入 < €10m，且税前利润 < €1m','Revenue < EUR 10m and profit before tax < EUR 1m','Umsatz < 10 Mio. EUR und Gewinn vor Steuern < 1 Mio. EUR'),`ETR ≥ ${a.rate||'—'}%${a.etr!==null?' · '+new Intl.NumberFormat(lang,{maximumFractionDigits:2}).format(a.etr)+'%':''}`,T('税前利润 ≤ SBIE','Profit before tax ≤ SBIE','Gewinn vor Steuern ≤ SBIE')];return a.tests.map((v,i)=>`<div class="test-row"><div>${names[i]} ${help(['safe','etr','sbie'][i])}<small>${desc[i]}</small></div><span class="test-status">${v===null?T('待判断','Not determined','Ungeklärt'):v?T('✓ 数值满足','✓ Numerical pass','✓ Zahlen erfüllt'):T('○ 数值不满足','○ Numerical fail','○ Zahlen nicht erfüllt')}</span></div>`).join('')}
function resultCard(title,label,body,topic){const g=topicData()[topic];return `<article class="panel result"><div class="result-head"><h3>${title} ${help(topic)}</h3><span class="badge">${label}</span></div><div class="result-body">${body}</div><details><summary>${T('判断依据与下一步','Basis and next steps','Grundlage und nächste Schritte')}</summary><p>${g.text}</p>${refs(g.refs)}</details></article>`}
function scopeText(a){return T(`前四年中 ${a.hits} 年达到 €750m，${a.missing} 年收入未知。`,`Revenue reaches EUR 750m in ${a.hits} of the preceding four years; ${a.missing} year(s) are unknown.`,`In ${a.hits} der vier Vorjahre werden 750 Mio. EUR erreicht; ${a.missing} Jahr(e) sind ungeklärt.`)}
function reportPage(){const a=P2.evaluate(d),out=a.scope==='no',conditional=a.scope!=='yes';const none=T('本情景暂不触发；如输入或特殊情况改变，请重新评估。','Not triggered on the stated assumptions; reassess if inputs or special circumstances change.','Unter den angegebenen Annahmen nicht ausgelöst; bei Änderungen erneut prüfen.');const dependency=T('以下申报路径以确认进入适用范围为前提。','The following filing routes are conditional on confirmed scope.','Die folgenden Meldewege setzen einen bestätigten Anwendungsbereich voraus.');return heading(5,T('你的 Pillar 2 义务路线图。','Your Pillar Two assessment.','Ihre Pillar-Two-Übersicht.'),`${esc(d.name||T('未命名企业','Unnamed entity','Einheit ohne Namen'))} · ${d.year} · ${isDemo?T('虚构演示案例','Fictional demonstration','Fiktives Beispiel'):T('用户填写数据','User-provided inputs','Nutzerangaben')}`)+`<div class="export"><button class="primary" id="print">${T('生成 PDF／打印','Generate PDF / print','PDF erstellen / drucken')}</button><button class="secondary" id="download">${T('导出 HTML 报告','Export HTML report','HTML-Bericht exportieren')}</button></div><p class="hint">${T('PDF 使用浏览器打印窗口中的“保存为 PDF”，按当前语言生成，包含输入快照和法条。','Use “Save as PDF” in the print dialog. The report uses the current language and includes inputs and legal references.','Im Druckdialog „Als PDF sichern“ wählen. Der Bericht erscheint in der aktuellen Sprache, einschließlich Eingaben und Rechtsgrundlagen.')}</p>${conditional?`<div class="notice">${dependency}</div>`:''}`+resultCard('01 '+T('适用范围','Scope','Anwendungsbereich'),status(a.scope),`<p>${scopeText(a)}</p>`,'scope')+resultCard('02 '+T('集团结构与跨国义务','Group structure and cross-border duties','Gruppenstruktur und grenzüberschreitende Pflichten'),a.structureUnknown?unknown():T('结构定位','Structure mapping','Struktureinordnung'),`<p>${a.eu.length?T('上层欧盟实体所在地：','Upper EU entities: ','Übergeordnete EU-Einheiten: ')+a.eu.map(p=>esc(country(p.country))).join(' → '):T('已填写持股链中未识别欧盟上层母公司。','No EU upper parent identified in the entered chain.','In der angegebenen Kette wurde keine übergeordnete EU-Muttergesellschaft identifiziert.')}</p><p>${iirText(a.iir)}</p><p>${T('其他国家仅提示需评估的路径，未作当地法律结论。','Foreign jurisdictions are flagged for assessment; no local-law conclusion is made.','Für andere Staaten werden Prüfpfade aufgezeigt, jedoch keine lokalen Rechtsfolgen abschließend bestimmt.')}</p>`,'iir')+resultCard('03 Gruppenträgermeldung',out?status('no'):T('德国集团层面','German group level','Deutsche Gruppenebene'),`<p>${out?none:roleText(a.role)}</p>${out?'':`<p>${d.notificationDone==='yes'?T('已填写完成通知；继续核查后续变更。','Notification marked complete; check subsequent changes.','Meldung als erledigt angegeben; spätere Änderungen prüfen.'):a.notification?T('如需首次通知，名义基准期限：','If initial notification is required, nominal reference deadline: ','Falls eine Erstmeldung erforderlich ist, nominelle Referenzfrist: ')+a.notification:unknown()}</p>`}`,'notification')+resultCard('04 '+T('过渡期 CbCR 安全港','Transitional CbCR Safe Harbour','CbCR-Safe-Harbour'),status(a.sh),`${out?`<p>${T('范围未触发：下列仅为独立数值演算。','Scope not triggered: the following is a standalone numerical illustration.','Kein Anwendungsfall festgestellt: Nachfolgend nur eine eigenständige Zahlenprüfung.')}</p>`:''}${testHTML(a)}`,'safe')+resultCard('05 GIR / Mindeststeuer-Bericht',out?status('no'):T('独立信息报告','Separate information return','Eigenständiger Bericht'),`<p>${out?none:girText(a.gir)}</p>${out?'':`<p>${a.due?T('日历财年法定基准期限：','Statutory reference deadline for a calendar fiscal year: ','Gesetzliche Referenzfrist bei Kalendergeschäftsjahr: ')+a.due:T('财年或首次编报信息不全，暂不确定期限。','Fiscal-year or first-reporting-year details are incomplete; no deadline determined.','Geschäftsjahr oder erstmaliges Berichtsjahr ungeklärt; keine Frist bestimmt.')}</p>`}`,'gir')+resultCard('06 '+T('德国税务申报与支付','German tax return and payment','Deutsche Steuererklärung und Zahlung'),out?status('no'):T('税额未计算','Tax not calculated','Steuer nicht berechnet'),`<p>${out?none:T('由德国 Gruppenträger 核查独立的最低税申报。Safe Harbour 或境外 GIR 不自动消除该义务。','The German group head must review the separate minimum tax return. A safe harbour or foreign GIR does not automatically remove this duty.','Der deutsche Gruppenträger muss die gesonderte Mindeststeuererklärung prüfen. Safe Harbour oder ausländischer GIR beseitigen diese Pflicht nicht automatisch.')}</p>${!out&&a.due?`<p>${T('§ 95(2) 申报期限下限：','Section 95(2) earliest possible deadline: ','Frühestmögliches Fristende nach § 95 Abs. 2: ')}${a.due} · ${T('并非确定的最终截止日','not a determined final deadline','kein abschließend bestimmtes Fristende')}</p>`:''}`,'return')+panel(T('需要准备的证据','Evidence to prepare','Benötigte Nachweise'),`<ul>${[T('前四年集团合并报表与收入换算依据','Four years of consolidated accounts and revenue conversion evidence','Konzernabschlüsse der vier Vorjahre und Nachweise zur Währungsumrechnung'),T('完整持股链、外部持股比例及德国实体清单','Full ownership chain, external ownership percentages and German entity list','Vollständige Beteiligungskette, externe Beteiligungsquoten und Liste deutscher Einheiten'),T('安全港合格数据、调整及历史适用证据','Qualified safe harbour data, adjustments and prior-year evidence','Qualifizierte Safe-Harbour-Daten, Anpassungen und Vorjahresnachweise'),T('集团主体指定、GIR 提交与交换证据','Group head designation, GIR submission and exchange evidence','Bestimmung des Gruppenträgers, GIR-Übermittlung und Austauschnachweise')].map(x=>`<li>${x}</li>`).join('')}</ul>`)+`<p class="hint">${limits()}</p>`}
function limits(){return T('原型 v2 · 2026-11-05。限 2024–2026 日历财年常规初筛。日期未调整周末、节假日及延期。采用所列德国法条；历史版本及 2026 年 OECD 新措施的德国适用需另核。未计算补足税、未自动评估其他安全港、未向税局报送。','Prototype v2 · 2026-11-05. Standard screening for calendar years 2024–2026. Dates are not adjusted for weekends, holidays or extensions. Based on the cited German provisions; historical versions and German application of new 2026 OECD measures require separate review. No top-up tax calculation, automatic assessment of other safe harbours or tax authority submission.','Prototyp v2 · 05.11.2026. Standardvorprüfung für Kalendergeschäftsjahre 2024–2026. Fristen ohne Anpassung an Wochenenden, Feiertage oder Verlängerungen. Grundlage sind die genannten deutschen Vorschriften; historische Fassungen und die deutsche Anwendung neuer OECD-Maßnahmen von 2026 sind gesondert zu prüfen. Keine Steuerberechnung, automatische Prüfung anderer Safe Harbours oder Übermittlung an Behörden.')}
function updateLive(){const a=P2.evaluate(d);$('#live').innerHTML=[['01',T('收入门槛','Revenue threshold','Umsatzgrenze'),`${a.hits} / 4`,scopeText(a)],['02',T('德国适用范围','German scope','Deutscher Anwendungsbereich'),status(a.scope),''],['03',T('上层欧盟实体','Upper EU entities','Übergeordnete EU-Einheiten'),a.structureUnknown?unknown():String(a.eu.length),''],['04','CbCR Safe Harbour',status(a.sh),'']].map(([n,h,v,p])=>`<div class="live-card"><small>${n} / ${h}</small><h3>${v}</h3><p>${p}</p></div>`).join('');if($('#tests'))$('#tests').innerHTML=testHTML(a);if($('#chain'))$('#chain').innerHTML=chain()}
function render(){document.documentElement.lang=lang==='zh'?'zh-CN':lang;document.title='Pillar Two Navigator · '+T('德国','Germany','Deutschland');$('#language').value=lang;$('#glossary').textContent=T('术语索引','Glossary','Begriffsverzeichnis')+' ↗';$('#tagline').textContent=T('让义务有迹可循。','Clarity at every step.','Pflichten klar erkennen.');$('#privacy').textContent=T('输入仅在本页内存处理。语言切换保留数据；刷新页面将清除。','Inputs stay in page memory. Switching languages retains data; refreshing clears it.','Eingaben bleiben im Seitenspeicher. Sprachwechsel erhält die Daten; Neuladen löscht sie.');const labels=[T('适用范围','Scope','Anwendungsbereich'),T('集团结构','Group structure','Gruppenstruktur'),'Safe Harbour',T('申报路径','Filing route','Meldewege'),T('自查报告','Assessment','Prüfbericht')];$('#nav').innerHTML=labels.map((s,i)=>`<button data-step="${i}" class="${i===step?'active':''}" aria-label="${esc(s)}" ${i===step?'aria-current="step"':''}><span class="stepno">${i+1}</span><span>${s}</span></button>`).join('');$('#progress').textContent=T('步骤','Step','Schritt')+` 0${step+1} / 05`;$('#demo').textContent=T('载入演示案例','Load example','Beispiel laden')+' ↗';$('#reset').textContent=T('清空','Clear','Leeren');$('#demoBanner').hidden=!isDemo;$('#demoBanner').textContent=T('虚构演示数据 · 美国 → 荷兰 → 德国 · 可自由修改','Fictional example · US → Netherlands → Germany · Editable','Fiktives Beispiel · USA → Niederlande → Deutschland · Änderbar');$('#content').innerHTML=[scopePage,structurePage,safePage,filingPage,reportPage][step]();$('#prev').disabled=step===0;$('#prev').textContent='← '+T('上一步','Back','Zurück');$('#next').textContent=step===4?T('返回修改','Edit inputs','Angaben bearbeiten'):step===3?T('生成自查报告','Generate assessment','Prüfbericht erstellen')+' →':T('继续','Continue','Weiter')+' →';$('#footer').textContent=limits();$('#liveTitle').textContent=T('实时筛查','LIVE ASSESSMENT','LAUFENDE PRÜFUNG');$('#legalNote').innerHTML=`<span>§</span><h3>${T('每一步，都有依据。','A basis for every step.','Jeder Schritt mit Grundlage.')}</h3><p>${T('点击问号查看释义和相关法条。','Use the question marks for explanations and legal references.','Fragezeichen öffnen Erläuterungen und Rechtsgrundlagen.')}</p><a href="https://www.gesetze-im-internet.de/minstg/" target="_blank" rel="noopener">MinStG ↗</a>`;updateLive()}
function sync(){document.querySelectorAll('[data-key]').forEach(el=>d[el.dataset.key]=el.value);document.querySelectorAll('[data-revenue]').forEach(el=>d.revenues[Number(el.dataset.revenue)]=el.value);document.querySelectorAll('[data-parent-name]').forEach(el=>d.parents[Number(el.dataset.parentName)].name=el.value);document.querySelectorAll('[data-parent-country]').forEach(el=>d.parents[Number(el.dataset.parentCountry)].country=el.value)}
function showHelp(id,trigger){helpId=id;helpTrigger=trigger||helpTrigger;const all=topicData();$('#helpTitle').textContent=id==='all'?T('术语与法条索引','Terms and legal references','Begriffe und Rechtsgrundlagen'):all[id].title;$('#closeHelp').textContent=T('关闭','Close','Schließen')+' ×';$('#helpBody').innerHTML=(id==='all'?Object.entries(all):[[id,all[id]]]).map(([k,g])=>`<section class="glossary-entry"><h3>${g.title}</h3><p>${g.text}</p><div>${refs(g.refs)}</div></section>`).join('')+`<p class="hint">${T('中文为说明性译法；德国法律术语以法条原文为准。英文缩写参考 OECD／欧盟用语。','Chinese terms are explanatory translations. German statutory wording prevails; English acronyms follow OECD / EU usage.','Chinesische Begriffe sind erläuternde Übersetzungen. Maßgeblich bleibt der deutsche Gesetzeswortlaut; englische Abkürzungen folgen dem OECD-/EU-Sprachgebrauch.')}</p><a class="law" href="https://eur-lex.europa.eu/legal-content/${lang==='de'?'DE':'EN'}/TXT/?uri=CELEX%3A32022L2523" target="_blank" rel="noopener">EU 2022/2523 ↗</a>`;if(!$('#helpDialog').open)$('#helpDialog').showModal()}
function validate(){const bad=[...document.querySelectorAll('input')].find(x=>!x.checkValidity());if(bad){bad.reportValidity();return false}return true}
function go(n){sync();if(!validate())return;step=n;render();window.scrollTo({top:0,behavior:'smooth'})}
function sample(){d={...blank(),name:'Rheinwerk Deutschland GmbH',group:'yes',standard:'yes',special:'no',germany:'yes',revenues:['680','760','810','720'],upe:'US',upeName:'Rheinwerk Global Inc.',parents:[{name:'Rheinwerk Europe B.V.',country:'NL'}],single:'yes',common:'no',designated:'no',holds:'yes',partial:'no',upperIIR:'yes',qualified:'yes',adjusted:'yes',shSpecial:'no',history:'eligible',shRevenue:'85',profit:'6',tax:'1.2',sbie:'2.4',first:'no',girWhere:'foreign',girEntity:'Rheinwerk Europe B.V.',girCountry:'NL',girFiled:'no',exchange:'yes',notificationDone:'yes'};isDemo=true;step=0;render()}
$('#language').addEventListener('change',e=>{sync();const expanded=[...document.querySelectorAll('#content details')].map(x=>x.open);lang=e.target.value;render();document.querySelectorAll('#content details').forEach((x,i)=>x.open=!!expanded[i]);if($('#helpDialog').open)showHelp(helpId);});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='language')return;if(el.dataset.key==='year'){sync();d.revenues=['','','',''];render();return}sync();updateLive()});
document.addEventListener('change',e=>{if(e.target.id!=='language'){sync();updateLive()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.help){showHelp(b.dataset.help,b);return}if(b.id==='glossary'){showHelp('all',b);return}if(b.id==='closeHelp')$('#helpDialog').close();if(b.dataset.step!==undefined)go(Number(b.dataset.step));if(b.id==='next')go(step===4?0:step+1);if(b.id==='prev')go(step-1);if(b.id==='addParent'){sync();d.parents.push({name:'',country:'unknown'});render()}if(b.dataset.remove!==undefined){sync();d.parents.splice(Number(b.dataset.remove),1);render()}if(b.id==='demo')sample();if(b.id==='reset'&&confirm(T('清空全部输入和结果？','Clear all inputs and results?','Alle Eingaben und Ergebnisse löschen?'))){d=blank();step=0;isDemo=false;render()}if(b.id==='print'){sync();$('#printReport').innerHTML=reportDocument();window.print()}if(b.id==='download')download()});
$('#helpDialog').addEventListener('close',()=>{if(helpTrigger?.isConnected)helpTrigger.focus();helpId=null});
function snapshotHTML(){const f=fields(),sets=optionSets();const rows=Object.keys(f).map(k=>{const options=sets[k]||(['upe','girCountry'].includes(k)?sets.countries:sets.yn);const v=['name','upeName','girEntity','shRevenue','profit','tax','sbie'].includes(k)?d[k]:options[d[k]]??d[k];return `<tr><th>${f[k][0]}</th><td>${esc(v===''?unknown():v)}</td></tr>`});d.revenues.forEach((v,i)=>rows.push(`<tr><th>${Number(d.year)-4+i} · ${T('集团收入','Group revenue','Konzernumsatz')} (€m)</th><td>${esc(v===''?unknown():v)}</td></tr>`));d.parents.forEach((p,i)=>rows.push(`<tr><th>${T('中间母公司','Intermediate parent','Zwischengeschaltete Muttergesellschaft')} ${i+1}</th><td>${esc(p.name)} · ${esc(country(p.country))}</td></tr>`));return `<h2>${T('输入快照','Input snapshot','Eingabeübersicht')}</h2><table>${rows.join('')}</table>`}
function reportDocument(){const report=reportPage().replace(/<div class="export">[\s\S]*?<\/div>/,'').replace(/<button\b[^>]*>[\s\S]*?<\/button>/g,'').replace(/<details>/g,'<details open>');return `<h1>Pillar Two Navigator</h1>${report}${snapshotHTML()}<h2>${T('术语索引','Glossary','Begriffsverzeichnis')}</h2>${Object.values(topicData()).map(g=>`<section class="print-term"><h3>${g.title}</h3><p>${g.text}</p>${refs(g.refs)}</section>`).join('')}`}
function download(){sync();const style='body{max-width:900px;margin:30px auto;padding:20px;font:14px/1.7 system-ui,sans-serif;color:#173d38}article,.panel{border:1px solid #ccd8ce;padding:18px;margin:20px 0}a{color:#14644d}table{border-collapse:collapse;width:100%}th,td{border-bottom:1px solid #ccc;text-align:left;padding:8px;vertical-align:top}th{width:60%}small{display:block}.test-row{margin:12px 0}.badge{font-weight:bold}.hint{font-size:12px}';const html=`<!doctype html><html lang="${lang==='zh'?'zh-CN':lang}"><meta charset="utf-8"><title>Pillar Two ${d.year}</title><style>${style}</style><body>${reportDocument()}</body></html>`,url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`Pillar-Two-${d.year}-${lang}.html`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
window.addEventListener('beforeprint',()=>{sync();$('#printReport').innerHTML=reportDocument()});
render();
